#!/usr/bin/env bash
# Generated by opencode-deployment-governance for LCP #712/#729.
# Source: deploy/production.yaml
# Default is dry-run validation. Mutating deploy requires --execute.
set -euo pipefail

MODE="dry-run"
SOURCE="/opt/laudium-post/.deploy-candidates/lcp712-frontend-only-3b6d8d27/source-frontend"
IMAGE_TAG="laudium-post-frontend:latest"
RELEASE_TAG="laudium-post-frontend:lcp712-3b6d8d27-api-base-cors-20260519"
ROLLBACK_TAG="laudium-post-frontend:rollback-lcp712-frontend-only-predeploy-20260519"
COMPOSE_PROJECT="laudium-post"
COMPOSE_FILE="/opt/laudium-post/docker-compose.prod.yml"
APP_DIR="/opt/laudium-post"
EXPECTED_API="https://laudiumpost.co.za/laudium/api/v1/"
FORBIDDEN_API="https://server.safai.co.za/Laudiumbiz/api/v1/"

while [[ $# -gt 0 ]]; do
  case "$1" in
    --execute) MODE="execute"; shift ;;
    --dry-run|--validate) MODE="dry-run"; shift ;;
    --contract-only) MODE="contract-only"; shift ;;
    --source) SOURCE="$2"; shift 2 ;;
    *) echo "unknown argument: $1" >&2; exit 2 ;;
  esac
done

cd "$APP_DIR"
test -f "$COMPOSE_FILE"
docker compose -p "$COMPOSE_PROJECT" -f "$COMPOSE_FILE" config --services | grep -Fx frontend >/dev/null
docker compose -p "$COMPOSE_PROJECT" -f "$COMPOSE_FILE" config --services | grep -Fx backend >/dev/null
docker compose -p "$COMPOSE_PROJECT" -f "$COMPOSE_FILE" config --services | grep -Fx mysql >/dev/null
if [[ "$MODE" == "contract-only" ]]; then
  echo "contract-only validation ok; source artifact not checked and no deployment action executed"
  exit 0
fi
