  echo "dry-run only; no image build, tag, compose up, backend, mysql, DB, or volume action executed"
  exit 0
fi

docker tag "$PREVIOUS_IMAGE" "$ROLLBACK_TAG"
printf 'PREVIOUS_FRONTEND_IMAGE=%s\nROLLBACK_TAG=%s\n' "$PREVIOUS_IMAGE" "$ROLLBACK_TAG" > deploy/frontend-rollback-lcp712.env
docker build -t "$RELEASE_TAG" -t "$IMAGE_TAG" "$SOURCE"
docker compose -p "$COMPOSE_PROJECT" -f "$COMPOSE_FILE" up -d --no-deps frontend
